<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
type Source={id:string;name:string;type:string;jdbcUrl:string;username:string};type Dataset={id:string;name:string;sql:string;dataSourceId:string};type Preview={columns:string[];rows:Record<string,unknown>[];rowCount:number;truncated:boolean;queryId:string}
const sources=ref<Source[]>([]),datasets=ref<Dataset[]>([]),preview=ref<Preview|null>(null),busy=ref(false),notice=ref(''),error=ref('')
const apiKey=ref(sessionStorage.getItem('smartbi.apiKey')||'')
const source=reactive({name:'',type:'POSTGRESQL',jdbcUrl:'jdbc:postgresql://analytics-db:5432/analytics',username:'analytics_reader',credentialReference:'env://EXTERNAL_ANALYTICS_PASSWORD'})
const dataset=reactive({name:'',dataSourceId:'',sql:'select id, region, amount from sales where amount >= :minimum order by id'});const parameters=ref('{"minimum": 100}')
async function api(path:string,init?:RequestInit){sessionStorage.setItem('smartbi.apiKey',apiKey.value);const response=await fetch(path,{headers:{'Content-Type':'application/json','X-API-Key':apiKey.value},...init});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.message||`HTTP ${response.status}`);return body}
async function load(){try{[sources.value,datasets.value]=await Promise.all([api('/api/v1/data-sources'),api('/api/v1/datasets')]);if(!dataset.dataSourceId&&sources.value[0])dataset.dataSourceId=sources.value[0].id}catch(e){error.value=e instanceof Error?e.message:'加载失败'}}
async function createSource(){await act(async()=>{const saved=await api('/api/v1/data-sources',{method:'POST',body:JSON.stringify(source)});sources.value.push(saved);dataset.dataSourceId=saved.id;notice.value='数据源已保存；凭据引用未由 API 返回。'})}
async function testSource(id:string){await act(async()=>{const result=await api(`/api/v1/data-sources/${id}/test`,{method:'POST'});notice.value=`连接成功：${result.product}，${result.latencyMs} ms`})}
async function createDataset(){await act(async()=>{const saved=await api('/api/v1/datasets',{method:'POST',body:JSON.stringify(dataset)});datasets.value.push(saved);notice.value='数据集已创建'})}
async function runPreview(item:Dataset){await act(async()=>{const queryId=crypto.randomUUID();preview.value=await api(`/api/v1/datasets/${item.id}/preview`,{method:'POST',body:JSON.stringify({queryId,parameters:JSON.parse(parameters.value),page:0,size:100})});notice.value=`已返回 ${preview.value?.rowCount} 行`})}
async function act(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
onMounted(load)
</script>
<template><main><header><div><span class="eyebrow">SMARTBI QUERY ENGINE</span><h1>安全数据查询工作台</h1><p>外部 PostgreSQL 数据源、只读 SQL 数据集与参数化预览。</p></div><span class="badge">最大 500 行</span></header><label>API Key<input v-model="apiKey" type="password" autocomplete="off"/><button class="secondary" @click="load">登录并加载</button></label><p v-if="error" class="error">{{error}}</p><p v-if="notice" class="success">{{notice}}</p>
<section class="grid"><article class="panel"><h2>1. 数据源</h2><label>名称<input v-model="source.name" placeholder="分析库"/></label><label>JDBC URL<input v-model="source.jdbcUrl"/></label><div class="cols"><label>只读用户名<input v-model="source.username"/></label><label>服务端凭据引用<input v-model="source.credentialReference"/></label></div><p class="hint">只接受 env:// 引用，API 永不返回凭据引用或密码。</p><button :disabled="busy||!source.name" @click="createSource">保存数据源</button><ul><li v-for="item in sources" :key="item.id"><div><strong>{{item.name}}</strong><small>{{item.username}} · {{item.type}}</small></div><button class="secondary" @click="testSource(item.id)">测试连接</button></li></ul></article>
<article class="panel"><h2>2. SQL 数据集</h2><label>名称<input v-model="dataset.name" placeholder="销售明细"/></label><label>绑定数据源<select v-model="dataset.dataSourceId"><option disabled value="">请选择</option><option v-for="item in sources" :value="item.id" :key="item.id">{{item.name}}</option></select></label><label>只读 SQL<textarea v-model="dataset.sql" rows="7" spellcheck="false"/></label><button :disabled="busy||!dataset.name||!dataset.dataSourceId" @click="createDataset">创建数据集</button></article></section>
<section class="panel wide"><div class="title"><h2>3. 参数化预览</h2><label>参数 JSON<input v-model="parameters"/></label></div><table><thead><tr><th>数据集</th><th>SQL</th><th></th></tr></thead><tbody><tr v-for="item in datasets" :key="item.id"><td>{{item.name}}</td><td><code>{{item.sql}}</code></td><td><button class="secondary" :disabled="busy" @click="runPreview(item)">预览</button></td></tr></tbody></table><div v-if="preview" class="result"><p>{{preview.rowCount}} 行<span v-if="preview.truncated"> · 已截断</span></p><div class="scroll"><table><thead><tr><th v-for="c in preview.columns" :key="c">{{c}}</th></tr></thead><tbody><tr v-for="(row,i) in preview.rows" :key="i"><td v-for="c in preview.columns" :key="c">{{row[c]}}</td></tr></tbody></table></div></div></section></main></template>
